INSERT INTO `events` VALUES (1,'Koncert Rockowy','2025-12-15 19:00:00','Warszawa, Klub Stodoła',150.00,'Muzyka','https://dynamicmedia.livenationinternational.com/t/x/s/3dfccdaf-4426-4495-9834-3c4b1212eee6.jpg','2h 30min','19:00 - Otwarcie bramek\n19:30 - Support: Zespół Disco Adamus\n20:15 - Przerwa techniczna\n20:30 - Gwiazda wieczoru\n22:30 - Zakończenie','To będzie najgłośniejsze wydarzenie sezonu! Legendy rocka wracają na scenę, by zagrać swoje największe hity. Przygotuj się na niesamowite solówki gitarowe, potężne nagłośnienie i energię, która poniesie tłum. Nie może Cię tam zabraknąć!',NULL),(2,'Wielki Stand-up Show','2026-11-24 20:00:00','Klub Komediowy, Kraków',99.00,'Rozrywka','https://comedycarnival.co.uk/wp-content/uploads/2022/04/Leicester-Square-Comedy-Club-2-e1649097245592.jpg','120 min','19:00 - Otwarcie bramek\r\n	19:30 - Show Grzesia\r\n	20:00 - Show Stasia\r\n	20:30 - Show Zbyszka\r\n	21:00 - Wielkie Show Andżeliki\r\n	22:00 - Zakończenie','Wieczór pełen humoru w Klubie Komediowym! Na scenie wystąpią najlepsi komicy: Grzesio, Stasio, Zbyszek i Andżelika. Przygotuj się na 120 minut błyskotliwych żartów, improwizacji i świetnej zabawy. Idealny sposób na oderwanie się od codzienności.',NULL),(3,'Koncert Disco Adamus','2026-03-21 20:00:00','Klub Studio, Kraków',67.67,'Muzyka','https://i.ytimg.com/vi/DwXt9oOBt8Y/maxresdefault.jpg','167 min','19:00 - Otwarcie bramek\r\n	20:00 - Support: Taylor Swift\r\n	20:30 - Gwiazda wieczoru - Disco Adamus\r\n	21:47 - Zakończenie','🔥 DISCO ADAMUS – Koncert LIVE: Największa Sigma w Twoim Mieście! 🔥\r\nPrzygotujcie się na najbardziej energetyczne wydarzenie sezonu! Na scenie wystąpi jedyny i niepowtarzalny Disco Adamus – człowiek, który podbił polski internet i sprawił, że słowo „Sigma” nabrało zupełnie nowego rytmu. To nie jest zwykły koncert, to prawdziwy wulkan pozytywnej energii i tanecznego szaleństwa!\r\nCzego możecie się spodziewać?\r\n✨ Wszystkie wiralowe hity – usłyszycie na żywo utwory, które generują miliony odsłon: od legendarnego „Sigma Boy”, przez „Białystok”, aż po najnowsze propozycje jak „Mango67”.\r\n✨ Niepodrabialny styl – Disco Adamus to gwarancja autentyczności, świetnego kontaktu z publicznością i zabawy bez barier.\r\n✨ Taneczna moc – połączenie klasycznego disco polo z nowoczesnym, tik-tokowym sznytem, które porwie do tańca każdego.\r\nDlaczego musisz tu być?\r\nDisco Adamus to obecnie jeden z najpopularniejszych twórców dla młodzieży i król internetowych trendów. Jego występy to nie tylko muzyka, ale show, które idealnie wpisuje się w klimat współczesnej popkultury.',NULL),(4,'Zawody w Biegu w Kaloszach','2026-05-10 12:00:00','Błonia Krakowskie, Kraków',25.00,'Sport','https://www.lechameau.com/cdn/shop/files/20250302-LeChameau-BoatRace-0774-KA.jpg?v=1746547520&width=2000','120 min','11:00 - Rejestracja uczestników\r\n    12:00 - Oficjalne otwarcie zawodów\r\n    12:15 - Bieg eliminacyjny\r\n    13:00 - Bieg finałowy\r\n    13:30 - Konkurs na najciekawsze kalosze\r\n    14:00 - Wręczenie nagród i zakończenie','🏃‍♂️ ZAWODY W BIEGU W KALOSZACH 🏃‍♀️\r\nNietypowe, zabawne i pełne rywalizacji wydarzenie sportowe dla każdego. Jeśli masz dystans do siebie, lubisz aktywność fizyczną i dobrą zabawę, to te zawody są właśnie dla Ciebie.\r\nNa uczestników czekają emocjonujące biegi w kaloszach na specjalnie przygotowanej trasie, liczne konkurencje dodatkowe oraz nagrody dla najszybszych i najbardziej kreatywnych zawodników.\r\nTo impreza rodzinna, integracyjna i totalnie na luzie. Liczy się nie tylko czas, ale też styl, humor i dobra energia.',NULL),(5,'Pokazy Strongmanów na Żywo','2026-04-18 19:00:00','Kino Kijów, Kraków',55.00,'Rozrywka','https://img.boop.pl/uploads/v/f76931810a.jpg?width=720','150 min','18:30 - Otwarcie wejść\r\n    19:00 - Oficjalne rozpoczęcie\r\n    19:10 - Prezentacja zawodników\r\n    19:25 - Konkurencje siłowe część I\r\n    20:20 - Przerwa\r\n    20:40 - Konkurencje siłowe część II\r\n    21:20 - Finałowy pokaz siły\r\n    21:30 - Zakończenie wydarzenia','💪 POKAZY STRONGMANÓW NA ŻYWO 💪\r\nSpektakularne widowisko siły, wytrzymałości i determinacji w samym sercu Krakowa. Na scenie Kina Kijów wystąpią czołowi strongmani, prezentując konkurencje znane z największych zawodów na świecie.\r\nPubliczność zobaczy między innymi podnoszenie potężnych ciężarów, spacer farmera, przeciąganie pojazdów oraz próby sił, które wykraczają poza granice ludzkich możliwości.\r\nWydarzenie ma charakter dynamicznego show z komentarzem prowadzącego, efektami wizualnymi i bezpośrednim kontaktem z widzami.',NULL),(6,'Turniej Wędkarski o Puchar Soliny','2026-07-04 06:00:00','Jezioro Solińskie, Solina',30.00,'Sport','https://d-art.ppstatic.pl/kadry/k/r/e7/c6/62ecb02f11853_o_medium.jpg','480 min','05:30 - Rejestracja uczestników\r\n    06:00 - Otwarcie zawodów i odprawa techniczna\r\n    06:15 - Rozpoczęcie łowienia\r\n    13:30 - Zakończenie połowów\r\n    14:00 - Ważenie i pomiary ryb\r\n    15:00 - Ogłoszenie wyników i wręczenie nagród\r\n    15:30 - Zakończenie turnieju','🎣 TURNIEJ WĘDKARSKI NAD SOLINĄ 🎣\r\nCałodniowe zawody wędkarskie w malowniczej scenerii Jeziora Solińskiego. Uczestnicy rywalizują o tytuł mistrza w dwóch niezależnych kategoriach.\r\nPierwsza kategoria to największa złowiona ryba, druga to najcięższa złowiona ryba. O zwycięstwie decydują oficjalne pomiary przeprowadzone przez sędziów zawodów.\r\nTurniej skierowany jest zarówno do amatorów, jak i doświadczonych wędkarzy. Liczy się cierpliwość, technika oraz odrobina szczęścia. Na najlepszych czekają puchary i nagrody rzeczowe.',498),(7,'Międzynarodowy Turniej MMA Amatorów Warsaw Open','2026-04-18 16:00:00','COS Torwar, Warszawa',55.00,'Sport','https://uww.org/static-assets/waf-images/29/c0/ab/0/29a3b4ee-2a8a-43c2-af0c-4e68d8940f64-62kg-PKMM---Scott-Bradley-Heathcote--CAN--df--Aayush-Dipu--IND-_2811.jpg','240 min','15:30 - Otwarcie hali\r\n    16:00 - Eliminacje\r\n    18:30 - Półfinały\r\n    19:45 - Finały\r\n    20:30 - Dekoracja zwycięzców','Międzynarodowy turniej MMA dla zawodników amatorskich. Uczestnicy z Polski, Niemiec i Litwy. Walki w kilku kategoriach wagowych z pełną oprawą sportową.',NULL),(8,'Spektakl Improwizacji Teatralnej Hulaj Impro','2026-03-22 19:00:00','Teatr Capitol, Warszawa',40.00,'Rozrywka','https://teatrwkrakowie.pl/images/upload/Galerie_foto/Aktorzy/Andrzej_Grabowski/Irydion_1983_Trela_Matysik_Grabowski_Bielska_fot_W_Plewinski_detailGallery.jpg','100 min','18:30 - Otwarcie drzwi\r\n    19:00 - Start spektaklu\r\n    20:40 - Zakończenie','Spektakl improwizowany grupy Hulaj Impro, tworzonej z sugestii publiczności. Dynamiczne sceny, absurdalny humor i interakcja z widzami.',NULL),(9,'Koncert Muzyki Filmowej John Williams Symphonic','2026-05-23 20:00:00','Narodowe Forum Muzyki, Wrocław',130.00,'Muzyka','https://d-art.ppstatic.pl/kadry/k/r/98/b8/58bbf76f449af_o_medium.jpg','115 min','19:30 - Wejście publiczności\r\n    20:00 - Koncert\r\n    21:55 - Zakończenie','Koncert symfoniczny poświęcony muzyce filmowej Johna Williamsa. Na żywo utwory z Gwiezdnych Wojen, Harry’ego Pottera i Parku Jurajskiego.',NULL),(10,'Pokaz Kaskaderski Monster Truck Baltic Show','2026-06-27 18:00:00','Ergo Arena, Gdańsk',70.00,'Rozrywka','https://www.monsterjam.com/wp-content/uploads/2024/04/Grave-Digger-2024.jpg','120 min','17:30 - Otwarcie bram\r\n    18:00 - Start show\r\n    19:50 - Finał','Widowisko motoryzacyjne z udziałem monster trucków i kaskaderów z Europy. Skoki, kraksy kontrolowane i ekstremalne przejazdy.',NULL),(11,'Widowisko Laserowe Neon Pulse','2026-04-10 21:00:00','Hala Stulecia, Wrocław',55.00,'Rozrywka','https://www.phaeno.de/fileadmin/_processed_/3/5/csm_Laserprojektoren_zaubern_ein_buntes_Lichtspektakel_ins_phaeno_Wissenschaftstheater_Foto_Matthias_Leitzke_92fbd0f28c.webp','95 min','20:30 - Wejście\r\n    21:00 - Show\r\n    22:35 - Zakończenie','Multimedialne widowisko laserowe połączone z muzyką elektroniczną i mappingiem 3D. Nowoczesna oprawa audiowizualna.',NULL),(12,'Kabaret Moralnego Niepokoju Program Premierowy','2026-05-15 19:30:00','Teatr Muzyczny Roma, Warszawa',85.00,'Rozrywka','https://nck.nisko.pl/wp-content/uploads/2022/10/Kabaret_Moralnego_Niepokoju-2-1068x741.jpg','105 min','19:00 - Otwarcie sali\r\n    19:30 - Występ\r\n    21:15 - Zakończenie','Premiera nowego programu Kabaretu Moralnego Niepokoju. Komentarz społeczny, humor sytuacyjny i kultowe postacie.',NULL),(13,'Turniej E-sportowy CS2 Baltic Masters','2026-06-21 12:00:00','AmberExpo, Gdańsk',45.00,'Rozrywka','https://news.sumdu.edu.ua/images/news/2021/2021-05-17/3/IMG_3943.jpg','360 min','11:30 - Wejście\r\n    12:00 - Grupy\r\n    16:30 - Półfinały\r\n    18:30 - Finał\r\n    19:30 - Wręczenie nagród','Turniej LAN Counter-Strike 2 z udziałem 8 profesjonalnych drużyn z Europy. Faza grupowa i wielki finał na scenie głównej.',NULL),(14,'Street Dance Battles Urban Flow','2026-07-11 18:00:00','Klub Stary Maneż, Gdańsk',50.00,'Rozrywka','https://ckibopalenica.pl/wp-content/uploads/2024/12/468525100_991085672828059_7926029838646447482_n_1024x682.jpg','150 min','17:30 - Rejestracja\r\n    18:00 - Eliminacje\r\n    20:00 - Finały\r\n    20:30 - Zakończenie','Ogólnopolski turniej street dance w formacie bitew. Style hip-hop, popping i locking. Profesjonalne jury i DJ na żywo.',NULL),(15,'Gala Boksu Zawodowego Warszawa Fight Night','2026-09-12 18:00:00','COS Torwar, Warszawa',90.00,'Sport','https://images.tapology.com/letterbox_images/7636/default/Marcin-Najman.jpeg?1334852741','210 min','17:30 - Otwarcie hali\r\n    18:00 - Walki wstępne\r\n    20:30 - Walki wieczoru\r\n    21:30 - Zakończenie','Profesjonalna gala boksu zawodowego z udziałem czołowych polskich pięściarzy. Walki rankingowe, pełna oprawa medialna i komentatorzy.',NULL),(16,'Gala Wrestlingu PTW Live','2026-10-03 19:00:00','Hala Stulecia, Wrocław',75.00,'Rozrywka','https://d2779tscntxxsw.cloudfront.net/5ea8360e7ccdb.png?width=1200&quality=80','150 min','18:30 - Wejście\r\n    19:00 - Start gali\r\n    21:30 - Zakończenie','Widowisko wrestlingowe na żywo organizowane przez Polish Traditional Wrestling. Postacie sceniczne, fabularne walki i interakcja z publicznością.',NULL),(17,'Koncert Elektroniczny C-Bool Live','2026-08-22 21:00:00','Klub Progresja, Warszawa',65.00,'Muzyka','https://www.opole.pl/sites/default/files/field_image/464198666_1123753985775315_5415021669237118331_n.jpg','120 min','20:30 - Otwarcie klubu\r\n    21:00 - Koncert\r\n    23:00 - Zakończenie','Koncert muzyki elektronicznej na żywo. C-Bool zaprezentuje największe hity klubowe oraz premierowe utwory w klubowej oprawie.',NULL),(18,'Festiwal Iluzji Marcin Muszyński Show','2026-11-14 18:30:00','Teatr Muzyczny, Gdynia',80.00,'Rozrywka','https://www.magic-man-show.com/wp-content/uploads/sites/8/2020/05/illusion-show-magician-e1604958530270.jpg','110 min','18:00 - Otwarcie drzwi\r\n    18:30 - Show\r\n    20:20 - Zakończenie','Sceniczny pokaz iluzji i mentalizmu w wykonaniu Marcina Muszyńskiego. Nowoczesna magia, interakcja z widzami i elementy psychologii.',NULL),(19,'Turniej Beer Pong Polska Liga','2026-07-25 17:00:00','Centrum Kongresowe ICE, Kraków',45.00,'Rozrywka','https://radio.foxnews.com/wp-content/uploads/2014/05/diane-keaton-for-wordpress.jpg','180 min','16:30 - Rejestracja\r\n    17:00 - Start turnieju\r\n    19:30 - Finały\r\n    20:00 - Zakończenie','Oficjalny turniej beer ponga w formule ligowej. Drużyny dwuosobowe, faza grupowa i finały na głównej scenie.',NULL),(20,'Motocross Freestyle FMX Masters','2026-06-13 18:00:00','Stadion Olimpijski, Wrocław',85.00,'Sport','https://img.redbull.com/images/c_crop,w_3200,h_1600,x_0,y_62/c_auto,w_1200,h_600/f_auto,q_auto/redbullcom/2017/05/22/5d81096a-bfcb-441a-86fd-6b6d7b839363/najlepszy-motocykl-na-poczatek-w-motocrossie-ktm-250-sx-f','120 min','17:30 - Otwarcie bram\r\n    18:00 - Start pokazów\r\n    19:50 - Finał','Pokaz motocross freestyle z udziałem najlepszych riderów z Europy. Skoki, salta i ewolucje na rampach.',NULL),(21,'Kabaret Skeczów Męczących Program Jubileuszowy','2026-10-17 19:30:00','Filharmonia Bałtycka, Gdańsk',95.00,'Rozrywka','https://upload.wikimedia.org/wikipedia/commons/6/69/Kabaret_Skeczow_Meczacych_-_plakat-02.jpg','110 min','19:00 - Wejście\r\n    19:30 - Występ\r\n    21:20 - Zakończenie','Jubileuszowy program Kabaretu Skeczów Męczących. Najlepsze skecze oraz nowe premiery sceniczne.',NULL),(22,'Turniej Szachów Blitz Grand Prix','2026-09-05 10:00:00','EXPO XXI, Warszawa',30.00,'Sport','https://www.stormontkingschess.com/wp-content/uploads/2024/02/chess-tournaments-1.jpg','300 min','09:30 - Rejestracja\r\n    10:00 - Rundy turniejowe\r\n    15:00 - Zakończenie','Turniej szachów błyskawicznych w formule open. Tempo 5+3, klasyfikacja generalna i nagrody pieniężne.',NULL),(23,'Maraton Horrorów - Terrifier','2026-10-31 22:00:00','Multikino Złote Tarasy, Warszawa',55.00,'Kino','https://static.android.com.pl/uploads/2024/10/Terrifier-3-recenzja-horror.jpg','300 min','21:30 - Wejście\r\n    22:00 - Seans 1 - Terrifier\r\n    00:00 - Seans 2 - Terrifier 2\r\n    02:00 - Seans 3 - Terrifier 3\r\n    03:00 - Zakończenie','Nocny maraton filmów grozy Terrifier. Trzy pełnometrażowe seanse bez przerw.',NULL),(24,'Pokaz Driftu Drift Masters Show','2026-08-08 17:00:00','Tor Wyścigów Konnych Służewiec, Warszawa',70.00,'Rozrywka','https://www.wsmp.pl/images/news/Kuba_Przygo%C5%84ski_S%C5%82omczyn.jpg','180 min','16:30 - Otwarcie bram\r\n    17:00 - Start pokazów\r\n    19:30 - Finał','Pokaz driftingu z udziałem zawodników Drift Masters European Championship. Przejazdy pokazowe, tandem i konkursy.',NULL);
